     1→import { create } from "zustand";
     2→import { persist } from "zustand/middleware";
     3→import { createStackForLocation } from "@/navigation/location-navigation";
     4→import { createTabNavigationState, popTo as popNavigationState, pushPage as pushNavigationState } from "@/navigation/tab-navigation";
     5→import { locationToUrl, normalizeSettingsSection, urlToLocation } from "@/navigation/navigation-meta";
     6→import type {
     7→  BreadcrumbStackItem,
     8→  DesktopLocation,
     9→  PushPageOptions,
    10→  TabNavigationState,
    11→} from "@/navigation/navigation-meta";
    12→
    13→export type PageViewMode = "skill" | "page";
    14→
    15→export interface PageTab {
    16→  id: string;
    17→  pinned: boolean;
    18→  historyIndex: number;
    19→  navigationHistory: TabNavigationState[];
    20→  viewMode?: PageViewMode;
    21→}
    22→
    23→export interface ClosedTabSnapshot {
    24→  tab: PageTab;
    25→  closedAt: number;
    26→  originIndex: number;
    27→}
    28→
    29→interface TabState {
    30→  tabs: PageTab[];
    31→  activeTabId: string | null;
    32→  recentlyClosedTabs: ClosedTabSnapshot[];
    33→}
    34→
    35→interface OpenTabInput {
    36→  pinned?: boolean;
    37→  viewMode?: PageViewMode;
    38→  navigationState: TabNavigationState;
    39→}
    40→
    41→export interface TabViewModel extends PageTab {
    42→  currentState: TabNavigationState | null;
    43→  currentLocation: DesktopLocation | null;
    44→  label: string;
    45→  icon?: BreadcrumbStackItem["icon"];
    46→  descriptorId?: string;
    47→  meta?: BreadcrumbStackItem["meta"];
    48→  url: string | null;
    49→}
    50→
    51→interface TabActions {
    52→  openTab: (tab: OpenTabInput) => string;
    53→  closeTab: (tabId: string) => void;
    54→  closeOtherTabs: (tabId: string) => void;
    55→  closeTabsToRight: (tabId: string) => void;
    56→  setActiveTab: (tabId: string) => void;
    57→  pinTab: (tabId: string) => void;
    58→  unpinTab: (tabId: string) => void;
    59→  setViewMode: (tabId: string, mode: PageViewMode) => void;
    60→  moveTab: (fromIndex: number, toIndex: number) => void;
    61→  navigate: (tabId: string, url: string) => void;
    62→  navigateToLocation: (tabId: string, location: DesktopLocation, patch?: Partial<TabNavigationState>) => void;
    63→  replaceLocation: (tabId: string, next: TabNavigationState) => void;
    64→  pushLocation: (tabId: string, next: TabNavigationState) => void;
    65→  insertHistoryBeforeCurrent: (tabId: string, next: TabNavigationState) => void;
    66→  pushPage: (
    67→    tabId: string,
    68→    item: BreadcrumbStackItem,
    69→    location: DesktopLocation,
    70→    options?: PushPageOptions
    71→  ) => void;
    72→  popTo: (tabId: string, index: number) => void;
    73→  resetStack: (tabId: string, next: TabNavigationState) => void;
    74→  jumpToHistory: (tabId: string, historyIndex: number) => void;
    75→  goBack: (tabId: string) => void;
    76→  goForward: (tabId: string) => void;
    77→  canGoBack: (tabId: string) => boolean;
    78→  canGoForward: (tabId: string) => boolean;
    79→  getCurrentUrl: (tabId: string) => string | null;
    80→  getCurrentNavigationState: (tabId: string) => TabNavigationState | null;
    81→  closeAllTabs: () => void;
    82→  duplicateTab: (tabId: string) => string | null;
    83→  reopenClosedTab: () => string | null;
    84→  restoreTab: (tab: PageTab) => void;
    85→}
    86→
    87→const generateTabId = () =>
    88→  `tab-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
    89→const MAX_RECENTLY_CLOSED_TABS = 20;
    90→export const TAB_STORE_STORAGE_KEY = "viben-tab-store-v2";
    91→
    92→function findLastPinnedIndex(tabs: PageTab[]): number {
    93→  for (let index = tabs.length - 1; index >= 0; index -= 1) {
    94→    if (tabs[index].pinned) {
    95→      return index;
    96→    }
    97→  }
    98→  return -1;
    99→}
   100→
   101→function buildFallbackLocation(url: string): DesktopLocation {
   102→  if (url.startsWith("/workspace/") && url.includes("/apps")) {
   103→    const parts = url.split("/").filter(Boolean);
   104→    const workspaceId = parts[1];
   105→    if (workspaceId) {
   106→      return { kind: "workspace-apps", workspaceId };
   107→    }
   108→  }
   109→
   110→  if (url.startsWith("/documents")) {
   111→    return { kind: "documents" };
   112→  }
   113→
   114→  if (url.startsWith("/devices/pair")) {
   115→    return { kind: "device-pair" };
   116→  }
   117→
   118→  if (url.startsWith("/settings")) {
   119→    const section = url.split("/")[2];
   120→    return { kind: "settings", section: normalizeSettingsSection(section) };
   121→  }
   122→
   123→  return { kind: "documents" };
   124→}
   125→
   126→function buildStateFromUrl(url?: string): TabNavigationState {
   127→  const location = (url ? urlToLocation(url) : null) ?? buildFallbackLocation(url ?? "/documents");
   128→  return createTabNavigationState(location, createStackForLocation(location));
   129→}
   130→
   131→function isNavigationState(value: unknown): value is TabNavigationState {
   132→  if (!value || typeof value !== "object") return false;
   133→  const candidate = value as Partial<TabNavigationState>;
   134→  return Boolean(candidate.location && Array.isArray(candidate.breadcrumbStack));
   135→}
   136→
   137→function isPersistedPageTab(value: unknown): value is PageTab {
   138→  if (!value || typeof value !== "object") return false;
   139→  const candidate = value as Partial<PageTab>;
   140→  return typeof candidate.id === "string" && Array.isArray(candidate.navigationHistory);
   141→}
   142→
   143→function isPersistedSnapshot(value: unknown): value is ClosedTabSnapshot {
   144→  if (!value || typeof value !== "object") return false;
   145→  const candidate = value as Partial<ClosedTabSnapshot>;
   146→  return (
   147→    isPersistedPageTab(candidate.tab) &&
   148→    typeof candidate.originIndex === "number" &&
   149→    typeof candidate.closedAt === "number"
   150→  );
   151→}
   152→
   153→function normalizeTab(tab: PageTab): PageTab {
   154→  const navigationHistory = tab.navigationHistory.filter(isNavigationState);
   155→  const safeHistory = navigationHistory.length > 0 ? navigationHistory : [buildStateFromUrl("/documents")];
   156→  const historyIndex = Math.min(
   157→    Math.max(tab.historyIndex ?? safeHistory.length - 1, 0),
   158→    safeHistory.length - 1
   159→  );
   160→
   161→  return {
   162→    id: tab.id,
   163→    pinned: Boolean(tab.pinned),
   164→    historyIndex,
   165→    navigationHistory: safeHistory,
   166→    viewMode: tab.viewMode,
   167→  };
   168→}
   169→
   170→function normalizeSnapshot(snapshot: ClosedTabSnapshot): ClosedTabSnapshot {
   171→  return {
   172→    tab: normalizeTab(snapshot.tab),
   173→    originIndex: snapshot.originIndex,
   174→    closedAt: snapshot.closedAt,
   175→  };
   176→}
   177→
   178→function cloneTabWithNewId(tab: PageTab, overrides?: Partial<PageTab>): PageTab {
   179→  return normalizeTab({
   180→    ...normalizeTab(tab),
   181→    ...overrides,
   182→    id: generateTabId(),
   183→  });
   184→}
   185→
   186→function createClosedSnapshot(tab: PageTab, originIndex: number): ClosedTabSnapshot {
   187→  return {
   188→    tab: normalizeTab(tab),
   189→    originIndex,
   190→    closedAt: Date.now(),
   191→  };
   192→}
   193→
   194→function pushClosedSnapshots(
   195→  stack: ClosedTabSnapshot[],
   196→  snapshots: ClosedTabSnapshot[]
   197→): ClosedTabSnapshot[] {
   198→  if (snapshots.length === 0) {
   199→    return stack;
   200→  }
   201→
   202→  return [...snapshots].reverse().concat(stack).slice(0, MAX_RECENTLY_CLOSED_TABS);
   203→}
   204→
   205→function restoreClosedTabIntoTabs(
   206→  tabs: PageTab[],
   207→  snapshot: ClosedTabSnapshot
   208→): { tabs: PageTab[]; restoredTab: PageTab } {
   209→  const restoredTab = cloneTabWithNewId(snapshot.tab);
   210→  const nextTabs = [...tabs];
   211→  const insertIndex = Math.max(0, Math.min(snapshot.originIndex, nextTabs.length));
   212→  nextTabs.splice(insertIndex, 0, restoredTab);
   213→  return { tabs: nextTabs, restoredTab };
   214→}
   215→
   216→export function getTabCurrentState(tab: PageTab): TabNavigationState | null {
   217→  return tab.navigationHistory[tab.historyIndex] ?? null;
   218→}
   219→
   220→export function getTabCurrentLeaf(tab: PageTab): BreadcrumbStackItem | null {
   221→  const current = getTabCurrentState(tab);
   222→  return current?.breadcrumbStack[current.breadcrumbStack.length - 1] ?? null;
   223→}
   224→
   225→export function getTabUrl(tab: PageTab): string | null {
   226→  const current = getTabCurrentState(tab);
   227→  return current ? locationToUrl(current.location) : null;
   228→}
   229→
   230→export function getTabViewModel(tab: PageTab): TabViewModel {
   231→  const currentState = getTabCurrentState(tab);
   232→  const leaf = getTabCurrentLeaf(tab);
   233→  const url = getTabUrl(tab);
   234→
   235→  return {
   236→    ...tab,
   237→    currentState,
   238→    currentLocation: currentState?.location ?? null,
   239→    label: leaf?.label ?? currentState?.location.kind ?? "Untitled",
   240→    icon: leaf?.icon,
   241→    descriptorId: leaf?.descriptorId,
   242→    meta: leaf?.meta,
   243→    url,
   244→  };
   245→}
   246→
   247→function findHistoryEntryByLocation(
   248→  navigationHistory: TabNavigationState[],
   249→  historyIndex: number,
   250→  location: DesktopLocation
   251→): number {
   252→  const targetUrl = locationToUrl(location);
   253→  for (let index = historyIndex - 1; index >= 0; index -= 1) {
   254→    if (locationToUrl(navigationHistory[index].location) === targetUrl) {
   255→      return index;
   256→    }
   257→  }
   258→  return -1;
   259→}
   260→
   261→export const useTabStore = create<TabState & TabActions>()(
   262→  persist(
   263→    (set, get) => ({
   264→      tabs: [],
   265→      activeTabId: null,
   266→      recentlyClosedTabs: [],
   267→
   268→      openTab: (tabData) => {
   269→        const id = generateTabId();
   270→        const newTab = normalizeTab({
   271→          id,
   272→          pinned: tabData.pinned ?? false,
   273→          navigationHistory: [tabData.navigationState],
   274→          historyIndex: 0,
   275→          viewMode: tabData.viewMode,
   276→        });
   277→
   278→        set((state) => ({
   279→          tabs: [...state.tabs, newTab],
   280→          activeTabId: id,
   281→        }));
   282→
   283→        return id;
   284→      },
   285→
   286→      closeTab: (tabId) => {
   287→        set((state) => {
   288→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   289→          if (tabIndex === -1) return state;
   290→
   291→          const recentlyClosedTabs = pushClosedSnapshots(
   292→            state.recentlyClosedTabs,
   293→            [createClosedSnapshot(state.tabs[tabIndex], tabIndex)]
   294→          );
   295→          const tabs = state.tabs.filter((tab) => tab.id !== tabId);
   296→          let activeTabId = state.activeTabId;
   297→
   298→          if (state.activeTabId === tabId) {
   299→            if (tabs.length === 0) {
   300→              activeTabId = null;
   301→            } else if (tabIndex >= tabs.length) {
   302→              activeTabId = tabs[tabs.length - 1].id;
   303→            } else {
   304→              activeTabId = tabs[tabIndex].id;
   305→            }
   306→          }
   307→
   308→          return { tabs, activeTabId, recentlyClosedTabs };
   309→        });
   310→      },
   311→
   312→      closeOtherTabs: (tabId) => {
   313→        set((state) => {
   314→          const snapshots = state.tabs
   315→            .map((tab, index) => ({ tab, index }))
   316→            .filter(({ tab }) => !tab.pinned && tab.id !== tabId)
   317→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   318→
   319→          return {
   320→            tabs: state.tabs.filter((tab) => tab.pinned || tab.id === tabId),
   321→            activeTabId: tabId,
   322→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   323→          };
   324→        });
   325→      },
   326→
   327→      closeTabsToRight: (tabId) => {
   328→        set((state) => {
   329→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   330→          if (tabIndex === -1) return state;
   331→
   332→          const snapshots = state.tabs
   333→            .map((tab, index) => ({ tab, index }))
   334→            .filter(({ tab, index }) => index > tabIndex && !tab.pinned)
   335→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   336→          const closingIds = new Set(snapshots.map((snapshot) => snapshot.tab.id));
   337→          const tabs = state.tabs.filter((tab) => !closingIds.has(tab.id));
   338→          const activeTabId = tabs.some((tab) => tab.id === state.activeTabId)
   339→            ? state.activeTabId
   340→            : tabId;
   341→
   342→          return {
   343→            tabs,
   344→            activeTabId,
   345→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   346→          };
   347→        });
   348→      },
   349→
   350→      setActiveTab: (tabId) => {
   351→        set({ activeTabId: tabId });
   352→      },
   353→
   354→      pinTab: (tabId) => {
   355→        set((state) => {
   356→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   357→          if (tabIndex === -1) return state;
   358→
   359→          const tab = state.tabs[tabIndex];
   360→          if (tab.pinned) return state;
   361→
   362→          const tabs = [...state.tabs];
   363→          tabs.splice(tabIndex, 1);
   364→
   365→          const insertIndex = findLastPinnedIndex(tabs) + 1;
   366→          tabs.splice(insertIndex, 0, { ...tab, pinned: true });
   367→
   368→          return { tabs };
   369→        });
   370→      },
   371→
   372→      unpinTab: (tabId) => {
   373→        set((state) => {
   374→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   375→          if (tabIndex === -1) return state;
   376→
   377→          const tab = state.tabs[tabIndex];
   378→          if (!tab.pinned) return state;
   379→
   380→          const tabs = [...state.tabs];
   381→          tabs.splice(tabIndex, 1);
   382→
   383→          const insertIndex = findLastPinnedIndex(tabs) + 1;
   384→          tabs.splice(insertIndex, 0, { ...tab, pinned: false });
   385→
   386→          return { tabs };
   387→        });
   388→      },
   389→
   390→      setViewMode: (tabId, mode) => {
   391→        set((state) => ({
   392→          tabs: state.tabs.map((tab) =>
   393→            tab.id === tabId ? { ...tab, viewMode: mode } : tab
   394→          ),
   395→        }));
   396→      },
   397→
   398→      moveTab: (fromIndex, toIndex) => {
   399→        set((state) => {
   400→          if (
   401→            fromIndex === toIndex ||
   402→            fromIndex < 0 ||
   403→            toIndex < 0 ||
   404→            fromIndex >= state.tabs.length ||
   405→            toIndex >= state.tabs.length
   406→          ) {
   407→            return state;
   408→          }
   409→
   410→          const tabs = [...state.tabs];
   411→          const [moved] = tabs.splice(fromIndex, 1);
   412→          tabs.splice(toIndex, 0, moved);
   413→          return { tabs };
   414→        });
   415→      },
   416→
   417→      navigate: (tabId, url) => {
   418→        get().pushLocation(tabId, buildStateFromUrl(url));
   419→      },
   420→
   421→      navigateToLocation: (tabId, location, patch) => {
   422→        get().pushLocation(
   423→          tabId,
   424→          createTabNavigationState(
   425→            location,
   426→            patch?.breadcrumbStack ?? createStackForLocation(location),
   427→            patch
   428→          )
   429→        );
   430→      },
   431→
   432→      replaceLocation: (tabId, next) => {
   433→        set((state) => ({
   434→          tabs: state.tabs.map((tab) => {
   435→            if (tab.id !== tabId) return tab;
   436→            const current = normalizeTab(tab);
   437→            const baseHistory = current.navigationHistory.slice(0, current.historyIndex);
   438→            return normalizeTab({
   439→              ...current,
   440→              navigationHistory: [...baseHistory, next],
   441→              historyIndex: baseHistory.length,
   442→            });
   443→          }),
   444→        }));
   445→      },
   446→
   447→      pushLocation: (tabId, next) => {
   448→        set((state) => ({
   449→          tabs: state.tabs.map((tab) => {
   450→            if (tab.id !== tabId) return tab;
   451→            const current = normalizeTab(tab);
   452→            const baseHistory = current.navigationHistory.slice(0, current.historyIndex + 1);
   453→            return normalizeTab({
   454→              ...current,
   455→              navigationHistory: [...baseHistory, next],
   456→              historyIndex: baseHistory.length,
   457→            });
   458→          }),
   459→        }));
   460→      },
   461→
   462→      insertHistoryBeforeCurrent: (tabId, next) => {
   463→        set((state) => ({
   464→          tabs: state.tabs.map((tab) => {
   465→            if (tab.id !== tabId) return tab;
   466→            const current = normalizeTab(tab);
   467→            const before = current.navigationHistory.slice(0, current.historyIndex);
   468→            const fromCurrent = current.navigationHistory.slice(current.historyIndex);
   469→            return normalizeTab({
   470→              ...current,
   471→              navigationHistory: [...before, next, ...fromCurrent],
   472→              historyIndex: before.length,
   473→            });
   474→          }),
   475→        }));
   476→      },
   477→
   478→      pushPage: (tabId, item, location, options) => {
   479→        const tab = get().tabs.find((entry) => entry.id === tabId);
   480→        const current = tab ? getTabCurrentState(normalizeTab(tab)) : null;
   481→        if (!current) return;
   482→        get().pushLocation(tabId, pushNavigationState(current, item, location, options));
   483→      },
   484→
   485→      popTo: (tabId, index) => {
   486→        const tab = get().tabs.find((entry) => entry.id === tabId);
   487→        const current = tab ? normalizeTab(tab) : null;
   488→        const currentState = current ? getTabCurrentState(current) : null;
   489→        if (!current || !currentState) return;
   490→
   491→        const nextState = popNavigationState(currentState, index);
   492→        const matchIndex = findHistoryEntryByLocation(
   493→          current.navigationHistory,
   494→          current.historyIndex,
   495→          nextState.location
   496→        );
   497→
   498→        if (matchIndex >= 0) {
   499→          get().jumpToHistory(tabId, matchIndex);
   500→          return;
   501→        }
   502→
   503→        get().insertHistoryBeforeCurrent(tabId, nextState);
   504→      },
   505→
   506→      resetStack: (tabId, next) => {
   507→        get().replaceLocation(tabId, next);
   508→      },
   509→
   510→      jumpToHistory: (tabId, historyIndex) => {
   511→        set((state) => ({
   512→          tabs: state.tabs.map((tab) => {
   513→            if (tab.id !== tabId) return tab;
   514→            const current = normalizeTab(tab);
   515→            return normalizeTab({
   516→              ...current,
   517→              historyIndex,
   518→            });
   519→          }),
   520→        }));
   521→      },
   522→
   523→      goBack: (tabId) => {
   524→        set((state) => ({
   525→          tabs: state.tabs.map((tab) => {
   526→            if (tab.id !== tabId) return tab;
   527→            const current = normalizeTab(tab);
   528→            if (current.historyIndex <= 0) return current;
   529→            return {
   530→              ...current,
   531→              historyIndex: current.historyIndex - 1,
   532→            };
   533→          }),
   534→        }));
   535→      },
   536→
   537→      goForward: (tabId) => {
   538→        set((state) => ({
   539→          tabs: state.tabs.map((tab) => {
   540→            if (tab.id !== tabId) return tab;
   541→            const current = normalizeTab(tab);
   542→            if (current.historyIndex >= current.navigationHistory.length - 1) {
   543→              return current;
   544→            }
   545→            return {
   546→              ...current,
   547→              historyIndex: current.historyIndex + 1,
   548→            };
   549→          }),
   550→        }));
   551→      },
   552→
   553→      canGoBack: (tabId) => {
   554→        const tab = get().tabs.find((item) => item.id === tabId);
   555→        return tab ? normalizeTab(tab).historyIndex > 0 : false;
   556→      },
   557→
   558→      canGoForward: (tabId) => {
   559→        const tab = get().tabs.find((item) => item.id === tabId);
   560→        if (!tab) return false;
   561→        const current = normalizeTab(tab);
   562→        return current.historyIndex < current.navigationHistory.length - 1;
   563→      },
   564→
   565→      getCurrentUrl: (tabId) => {
   566→        const tab = get().tabs.find((item) => item.id === tabId);
   567→        return tab ? getTabUrl(normalizeTab(tab)) : null;
   568→      },
   569→
   570→      getCurrentNavigationState: (tabId) => {
   571→        const tab = get().tabs.find((item) => item.id === tabId);
   572→        return tab ? getTabCurrentState(normalizeTab(tab)) : null;
   573→      },
   574→
   575→      closeAllTabs: () => {
   576→        set((state) => {
   577→          const snapshots = state.tabs
   578→            .map((tab, index) => ({ tab, index }))
   579→            .filter(({ tab }) => !tab.pinned)
   580→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   581→          const tabs = state.tabs.filter((tab) => tab.pinned);
   582→          return {
   583→            tabs,
   584→            activeTabId: tabs[0]?.id ?? null,
   585→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   586→          };
   587→        });
   588→      },
   589→
   590→      duplicateTab: (tabId) => {
   591→        const state = get();
   592→        const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   593→        if (tabIndex === -1) return null;
   594→
   595→        const duplicatedTab = cloneTabWithNewId(state.tabs[tabIndex], {
   596→          pinned: false,
   597→        });
   598→
   599→        set((current) => {
   600→          const tabs = [...current.tabs];
   601→          tabs.splice(tabIndex + 1, 0, duplicatedTab);
   602→          return {
   603→            tabs,
   604→            activeTabId: duplicatedTab.id,
   605→          };
   606→        });
   607→
   608→        return duplicatedTab.id;
   609→      },
   610→
   611→      reopenClosedTab: () => {
   612→        let restoredTabId: string | null = null;
   613→
   614→        set((current) => {
   615→          const [nextSnapshot, ...restSnapshots] = current.recentlyClosedTabs;
   616→          if (!nextSnapshot) return current;
   617→
   618→          const restored = restoreClosedTabIntoTabs(current.tabs, nextSnapshot);
   619→          restoredTabId = restored.restoredTab.id;
   620→
   621→          return {
   622→            tabs: restored.tabs,
