    88→        const agents: WorkspaceAgent[] = response.agents.map((a) => ({
    89→          id: a.id,
    90→          workspace_id: workspaceId,
    91→          name: a.name,
    92→          type: (a.type as any) || "UNKNOWN",
    93→          config_path: a.config_path || "",
