   189→export function useWorkspaceAgents(workspaceId: string | null) {
   190→  const [agents, setAgents] = useState<WorkspaceAgent[]>([]);
   191→  const [error, setError] = useState<string | null>(null);
   192→
   193→  // Get store functions directly (these are stable)
   194→  const startDiscovery = useWorkspaceStore((s) => s.startDiscovery);
   195→  const completeDiscovery = useWorkspaceStore((s) => s.completeDiscovery);
   196→  const failDiscovery = useWorkspaceStore((s) => s.failDiscovery);
   197→
   198→  // Subscribe to specific discovery task status for this workspace
   199→  // This ensures re-render when status changes
   200→  const discoveryTaskStatus = useWorkspaceStore(
   201→    (s) => workspaceId ? s.discoveryTasks[workspaceId]?.status : undefined
   202→  );
   203→  const discoveryTaskAgents = useWorkspaceStore(
   204→    (s) => workspaceId ? s.discoveryTasks[workspaceId]?.agents : undefined
   205→  );
   206→
   207→  const loading = discoveryTaskStatus === "running";
   208→
   209→  // Stable loadAgents function - only depends on workspaceId
   210→  const loadAgents = useCallback(async () => {
   211→    if (!workspaceId) {
   212→      setAgents([]);
   213→      return;
   214→    }
   215→
   216→    // Backpressure: don't start if already running
   217→    // Check directly from store state to avoid stale closure
   218→    const store = useWorkspaceStore.getState();
   219→    const currentTask = store.discoveryTasks[workspaceId];
   220→    if (currentTask?.status === "running") {
   221→      return;
   222→    }
   223→
   224→    startDiscovery(workspaceId);
   225→    setError(null);
   226→
   227→    try {
   228→      const client = getGatewayClient();
   229→      const response = await client.detectWorkspaceAgents(workspaceId);
   230→      // Transform gateway response to WorkspaceAgent (Executor) format
   231→      const result: WorkspaceAgent[] = response.agents.map((a) => ({
   232→        id: a.id,
   233→        workspace_id: workspaceId,
   234→        name: a.name,
   235→        type: (a.type as any) || "UNKNOWN",
   236→        config_path: a.config_path || "",
   237→        mcp_config_file: null,
   238→        skills_config_file: null,
   239→      }));
   240→      setAgents(result);
   241→      completeDiscovery(workspaceId, result);
   242→    } catch (err) {
   243→      const message = err instanceof Error ? err.message : String(err);
   244→      setError(message);
   245→      failDiscovery(workspaceId, message);
   246→    }
   247→  }, [workspaceId, startDiscovery, completeDiscovery, failDiscovery]);
   248→
   249→  // Initialize agents from existing discovery task or reset when workspace changes
   250→  // This handles both:
   251→  // 1. Navigating to a workspace where discovery already completed
   252→  // 2. Switching to a different workspace (need to reset)
   253→  useEffect(() => {
   254→    if (!workspaceId) {
   255→      setAgents([]);
   256→      setError(null);
   257→      return;
   258→    }
   259→
   260→    // Check if there's already completed discovery data for this workspace
   261→    const store = useWorkspaceStore.getState();
   262→    const task = store.discoveryTasks[workspaceId];
   263→    if (task?.status === "completed" && task.agents) {
   264→      // Use cached discovery results
   265→      setAgents(task.agents);
   266→    } else {
   267→      // No cached data, reset and wait for discovery
   268→      setAgents([]);
   269→    }
   270→    setError(null);
   271→  }, [workspaceId]);
   272→
   273→  // Keep agents in sync when discovery completes (from loadAgents call or elsewhere)
   274→  useEffect(() => {
   275→    if (discoveryTaskStatus === "completed" && discoveryTaskAgents) {
   276→      setAgents(discoveryTaskAgents);
   277→    }
   278→  }, [discoveryTaskStatus, discoveryTaskAgents]);
   279→
   280→  return {
   281→    agents,
   282→    loading,
   283→    error,
   284→    loadAgents,
   285→  };
   286→}
