   302→
   303→  const loadServers = useCallback(async () => {
   304→    if (!executorType) {
   305→      setServers([]);
   306→      return;
   307→    }
   308→
   309→    setLoading(true);
   310→    setError(null);
   311→    try {
   312→      const client = getGatewayClient();
   313→      const response = await client.getMcpServers(workspacePath ?? undefined, executorType);
   314→      setServers(response.servers);
   315→    } catch (err) {
   316→      const message = err instanceof Error ? err.message : String(err);
   317→      setError(message);
   318→    } finally {
   319→      setLoading(false);
   320→    }
   321→  }, [workspacePath, executorType]);
   322→
