     1→import { create } from "zustand";
     2→import { persist } from "zustand/middleware";
     3→import type { Workspace, WorkspaceAgent } from "@/types";
     4→
     5→/**
     6→ * Discovery task for a workspace - tracks auto-discovery progress
     7→ */
     8→export interface DiscoveryTask {
     9→  workspaceId: string;
    10→  status: "pending" | "running" | "completed" | "error";
    11→  startedAt: number;
    12→  completedAt?: number;
    13→  error?: string;
    14→  agents?: WorkspaceAgent[];
    15→}
    16→
    17→interface WorkspaceState {
    18→  // Workspaces list
    19→  workspaces: Workspace[];
    20→  activeWorkspaceId: string | null;
    21→  selectedAgentId: string | null;
    22→  isLoading: boolean;
    23→  error: string | null;
    24→
    25→  // Discovery tasks - track auto-discovery for each workspace
    26→  discoveryTasks: Record<string, DiscoveryTask>;
    27→
    28→  // Actions - Workspace management
    29→  setWorkspaces: (workspaces: Workspace[]) => void;
    30→  addWorkspace: (workspace: Workspace) => void;
    31→  removeWorkspace: (workspaceId: string) => void;
    32→  setActiveWorkspace: (workspaceId: string | null) => void;
    33→  updateWorkspaceAccessed: (workspaceId: string) => void;
    34→
    35→  // Actions - Agent selection
    36→  setSelectedAgentId: (agentId: string | null) => void;
    37→
    38→  // Actions - Loading state
    39→  setLoading: (loading: boolean) => void;
    40→  setError: (error: string | null) => void;
    41→
    42→  // Actions - Discovery tasks
    43→  startDiscovery: (workspaceId: string) => void;
    44→  completeDiscovery: (workspaceId: string, agents: WorkspaceAgent[]) => void;
    45→  failDiscovery: (workspaceId: string, error: string) => void;
    46→  clearDiscovery: (workspaceId: string) => void;
    47→
    48→  // Getters
    49→  getWorkspace: (workspaceId: string) => Workspace | undefined;
    50→  getWorkspaceByPath: (workspacePath: string) => Workspace | undefined;
    51→  getActiveWorkspace: () => Workspace | undefined;
    52→  getDiscoveryTask: (workspaceId: string) => DiscoveryTask | undefined;
    53→  hasRunningDiscovery: () => boolean;
    54→}
    55→
    56→export const useWorkspaceStore = create<WorkspaceState>()(
    57→  persist(
    58→    (set, get) => ({
    59→      // Initial state
    60→      workspaces: [],
    61→      activeWorkspaceId: null,
    62→      selectedAgentId: null,
    63→      isLoading: false,
    64→      error: null,
    65→      discoveryTasks: {},
    66→
    67→      // Workspace management
    68→      setWorkspaces: (workspaces) => set({ workspaces }),
    69→
    70→      addWorkspace: (workspace) =>
    71→        set((state) => ({
    72→          workspaces: [...state.workspaces, workspace],
    73→        })),
    74→
    75→      removeWorkspace: (workspaceId) =>
    76→        set((state) => {
    77→          const newWorkspaces = state.workspaces.filter(
    78→            (w) => w.id !== workspaceId
    79→          );
    80→          // Clear active workspace if it was removed
    81→          const activeId =
    82→            state.activeWorkspaceId === workspaceId
    83→              ? null
    84→              : state.activeWorkspaceId;
    85→          // Also remove discovery task
    86→          const { [workspaceId]: _, ...remainingTasks } = state.discoveryTasks;
    87→          return {
    88→            workspaces: newWorkspaces,
    89→            activeWorkspaceId: activeId,
    90→            discoveryTasks: remainingTasks,
    91→          };
    92→        }),
    93→
    94→      setActiveWorkspace: (workspaceId) =>
    95→        set({
    96→          activeWorkspaceId: workspaceId,
    97→          selectedAgentId: null, // Clear agent selection when switching workspace
    98→        }),
    99→
   100→      updateWorkspaceAccessed: (workspaceId) =>
   101→        set((state) => ({
   102→          workspaces: state.workspaces.map((w) =>
   103→            w.id === workspaceId
   104→              ? { ...w, last_accessed: new Date().toISOString() }
   105→              : w
   106→          ),
   107→        })),
   108→
   109→      // Agent selection
   110→      setSelectedAgentId: (agentId) => set({ selectedAgentId: agentId }),
   111→
   112→      // Loading state
   113→      setLoading: (loading) => set({ isLoading: loading }),
   114→      setError: (error) => set({ error }),
   115→
   116→      // Discovery tasks
   117→      startDiscovery: (workspaceId) =>
   118→        set((state) => ({
   119→          discoveryTasks: {
   120→            ...state.discoveryTasks,
   121→            [workspaceId]: {
   122→              workspaceId,
   123→              status: "running",
   124→              startedAt: Date.now(),
   125→            },
   126→          },
   127→        })),
   128→
   129→      completeDiscovery: (workspaceId, agents) =>
   130→        set((state) => ({
   131→          discoveryTasks: {
   132→            ...state.discoveryTasks,
   133→            [workspaceId]: {
   134→              ...state.discoveryTasks[workspaceId],
   135→              status: "completed",
   136→              completedAt: Date.now(),
   137→              agents,
   138→            },
   139→          },
   140→        })),
   141→
   142→      failDiscovery: (workspaceId, error) =>
   143→        set((state) => ({
   144→          discoveryTasks: {
   145→            ...state.discoveryTasks,
   146→            [workspaceId]: {
   147→              ...state.discoveryTasks[workspaceId],
   148→              status: "error",
   149→              completedAt: Date.now(),
   150→              error,
   151→            },
   152→          },
   153→        })),
   154→
   155→      clearDiscovery: (workspaceId) =>
   156→        set((state) => {
   157→          const { [workspaceId]: _, ...remainingTasks } = state.discoveryTasks;
   158→          return { discoveryTasks: remainingTasks };
   159→        }),
